/*
 * acl/test/test_acl_data.c - the ACL_ module data blocks (source-l2yd)
 *
 * Generated by: Claude Opus 5.5
 *
 * acl/acl_data.c is #included, so the objects under test are the real
 * blocks:
 *
 *   ACL_$WIRED_DATA    map "D E2C014 ACL_WIRED size = 14"
 *   ACL_$UNWIRED_DATA  map "D E7CF54 ACL_ size = BFC" (A5)
 *   ACL_$DATA          map "D69 E88834 ACL_$DATA size = AD98"
 *
 * Checked: the image addresses and sizes; every A5 offset of the unwired
 * block and every table offset of ACL_$DATA against the displacement the
 * assembly uses (from A5, from 0xE88834, or from the shared 0xE97294 base);
 * the bias arms (super_count[0] = cache_lru_head, each per-process table's
 * element 0 over the tail of the object before it); that pid N lands where
 * `base + N*stride' puts it; the image's initial contents (61 hash buckets
 * and the LRU head -1, the rest zero); and, through the real ACL_$UP and
 * ACL_$ENTER_SUPER, that the code indexes the tables with PROC1_$CURRENT.
 */

#include <stdint.h>
#include <stdio.h>
#include <string.h>

/* ==========================================================================
 * Test framework
 * ========================================================================== */

static int tests_failed = 0;
static int tests_run = 0;

#define TEST(name) static void test_##name(void)
#define RUN_TEST(name)                                                        \
    do {                                                                      \
        printf("  Running %s... ", #name);                                    \
        tests_run++;                                                          \
        test_##name();                                                        \
        printf("done\n");                                                     \
    } while (0)

#define ASSERT_EQ(expected, actual)                                           \
    do {                                                                      \
        long long _e = (long long)(expected);                                 \
        long long _a = (long long)(actual);                                   \
        if (_e != _a) {                                                       \
            printf("FAILED\n    Expected: 0x%llx, Got: 0x%llx at line %d\n",  \
                   (unsigned long long)_e, (unsigned long long)_a, __LINE__); \
            tests_failed++;                                                   \
            return;                                                           \
        }                                                                     \
    } while (0)

#include "acl/acl_internal.h"

uint16_t PROC1_$CURRENT;                /* PROC1_ASM cell 0xE20608 */

#include "../acl_data.c"
#include "../up.c"
#include "../enter_super.c"

#define OFF(block, field) \
    ((long long)((const uint8_t *)&(block).field - (const uint8_t *)&(block)))

/* image address of an ACL_$DATA field, and its displacement from the
 * 0xE97294 base the per-process code uses */
#define DVA(field)  ((long long)MODULE_DATA_ADDR(ACL_$DATA) + OFF(ACL_$DATA, field))
#define DISP(field) (DVA(field) - 0x00E97294LL)

/* ==========================================================================
 * Tests
 * ========================================================================== */

TEST(block_addresses_and_sizes)
{
    ASSERT_EQ(0x00E2C014u, MODULE_DATA_ADDR(ACL_$WIRED_DATA));
    ASSERT_EQ(0x00E7CF54u, MODULE_DATA_ADDR(ACL_$UNWIRED_DATA));
    ASSERT_EQ(0x00E88834u, MODULE_DATA_ADDR(ACL_$DATA));
    ASSERT_EQ(0xBFC, sizeof(ACL_$UNWIRED_DATA));
    ASSERT_EQ(0xAD98, sizeof(ACL_$DATA));
    /* map ACL_$SUPER_COUNT = super_count[1] */
    ASSERT_EQ(0x00E7DACCu, MODULE_DATA_ADDR(ACL_$UNWIRED_DATA) +
                               OFF(ACL_$UNWIRED_DATA, super_count[1]));
}

TEST(unwired_offsets)
{
    ASSERT_EQ(0x000, OFF(ACL_$UNWIRED_DATA, workspace));
    ASSERT_EQ(0x400, OFF(ACL_$UNWIRED_DATA, image_buf));
    ASSERT_EQ(0x800, OFF(ACL_$UNWIRED_DATA, cache_dir));
    ASSERT_EQ(0x9F0, OFF(ACL_$UNWIRED_DATA, cache_lru_links));
    ASSERT_EQ(0xA70, OFF(ACL_$UNWIRED_DATA, cache_hash_links));
    ASSERT_EQ(0xAF0, OFF(ACL_$UNWIRED_DATA, cache_hash_buckets));
    ASSERT_EQ(0xB6C, OFF(ACL_$UNWIRED_DATA, subs_magic));
    ASSERT_EQ(0xB70, OFF(ACL_$UNWIRED_DATA, local_locksmith));
    ASSERT_EQ(0xB72, OFF(ACL_$UNWIRED_DATA, locksmith_owner_pid));
    ASSERT_EQ(0xB74, OFF(ACL_$UNWIRED_DATA, cache_free_head));
    ASSERT_EQ(0xB76, OFF(ACL_$UNWIRED_DATA, cache_lru_head));
    ASSERT_EQ(0xBF8, OFF(ACL_$UNWIRED_DATA, locksmith_override));
}

/* super_count[pid] at A5 + 0xB76 + pid*2 (ACL_$ENTER_SUPER 0x00E46FA8) */
TEST(super_count_pid_n_is_element_n)
{
    int pid;
    for (pid = 0; pid < PROC1_MAX_PROCESSES; pid++) {
        ASSERT_EQ(0xB76 + pid * 2, OFF(ACL_$UNWIRED_DATA, super_count[pid]));
    }
    ASSERT_EQ(OFF(ACL_$UNWIRED_DATA, cache_lru_head), OFF(ACL_$UNWIRED_DATA, super_count[0]));
    ASSERT_EQ(0xBF8, OFF(ACL_$UNWIRED_DATA, super_count[PROC1_MAX_PROCESSES]));
}

/* Element 0 of each table at its displacement from 0xE97294. */
TEST(data_bias_slots_match_the_displacements)
{
    ASSERT_EQ(0x00E88834LL, DVA(acl_cache[0]));
    ASSERT_EQ(-0x6E84, DISP(original_sids[0]));
    ASSERT_EQ(-0x6584, DISP(current_sids[0]));
    ASSERT_EQ(-0x5C84, DISP(saved_sids[0]));
    ASSERT_EQ(-0x536C, DISP(saved_proj[0]));
    ASSERT_EQ(-0x506C, DISP(proj_lists[0]));
    ASSERT_EQ(-0x4DA0 + 8, DISP(proj_uids[0][0]));
    ASSERT_EQ(-0x4D60, DISP(asid_free_bitmap[0]));
    ASSERT_EQ(-0x3D5A, DISP(subsys_level[0]));
    ASSERT_EQ(-0x3CD8, DISP(locksmith_override_bitmap[0]));
    ASSERT_EQ(-0x3CD0, DISP(asid_suser_bitmap[0]));
    /* ACL_$INIT's constant-index stores (0x00E3110C, 0x00E3111A, 0x00E31132) */
    ASSERT_EQ(-0x6E48, DISP(original_sids[1].login_sid));
    ASSERT_EQ(-0x6548, DISP(current_sids[1].login_sid));
    ASSERT_EQ(0x00E9253CLL, DVA(proj_uids[1][0]));
}

/* Each bias slot overlays the tail of the object before it; element 1
 * follows that object's last element. */
TEST(bias_arms_chain)
{
    ASSERT_EQ(OFF(ACL_$DATA, acl_cache[ACL_CACHE_SLOTS]), OFF(ACL_$DATA, original_sids[1]));
    ASSERT_EQ(OFF(ACL_$DATA, original_sids[PROC1_MAX_PROCESSES]), OFF(ACL_$DATA, current_sids[1]));
    ASSERT_EQ(OFF(ACL_$DATA, current_sids[PROC1_MAX_PROCESSES]), OFF(ACL_$DATA, saved_sids[1]));
    ASSERT_EQ(OFF(ACL_$DATA, saved_sids[PROC1_MAX_PROCESSES]), OFF(ACL_$DATA, saved_proj[1]));
    ASSERT_EQ(OFF(ACL_$DATA, saved_proj[PROC1_MAX_PROCESSES]), OFF(ACL_$DATA, proj_lists[1]));
    ASSERT_EQ(OFF(ACL_$DATA, proj_lists[PROC1_MAX_PROCESSES]), OFF(ACL_$DATA, asid_free_bitmap));
    ASSERT_EQ(OFF(ACL_$DATA, asid_free_bitmap) + 8, OFF(ACL_$DATA, proj_uids[1]));
    ASSERT_EQ(OFF(ACL_$DATA, proj_uids[PROC1_MAX_PROCESSES]), OFF(ACL_$DATA, subsys_level[1]));
    ASSERT_EQ(OFF(ACL_$DATA, subsys_level[PROC1_MAX_PROCESSES]), OFF(ACL_$DATA, locksmith_override_bitmap));
    ASSERT_EQ(0xAD98, OFF(ACL_$DATA, asid_suser_bitmap) + 8);
}

/* pid N is element N at base + N*stride (ACL_$FREE_ASID 0x00E74C78..). */
TEST(pid_n_is_element_n)
{
    int pid;
    for (pid = 0; pid < PROC1_MAX_PROCESSES; pid++) {
        ASSERT_EQ(-0x6E84 + pid * 0x24, DISP(original_sids[pid]));
        ASSERT_EQ(-0x6584 + pid * 0x24, DISP(current_sids[pid]));
        ASSERT_EQ(-0x5C84 + pid * 0x24, DISP(saved_sids[pid]));
        ASSERT_EQ(-0x536C + pid * 0x0C, DISP(saved_proj[pid]));
        ASSERT_EQ(-0x506C + pid * 0x0C, DISP(proj_lists[pid]));
        ASSERT_EQ(-0x4DA0 + pid * 0x40 + 8, DISP(proj_uids[pid][0]));
        ASSERT_EQ(-0x3D5A + pid * 2, DISP(subsys_level[pid]));
    }
}

TEST(initial_contents)
{
    size_t i;
    const uint8_t *p;

    for (i = 0; i < ACL_CACHE_HASH_BUCKETS; i++) {
        ASSERT_EQ(-1, ACL_$UNWIRED_DATA.cache_hash_buckets[i]);
    }
    ASSERT_EQ(61, ACL_CACHE_HASH_BUCKETS);
    ASSERT_EQ(-1, ACL_$UNWIRED_DATA.cache_lru_head);
    ASSERT_EQ(-1, ACL_$UNWIRED_DATA.super_count[0]);
    p = (const uint8_t *)&ACL_$UNWIRED_DATA;
    for (i = 0; i < sizeof(ACL_$UNWIRED_DATA); i++) {
        if (i >= 0xAF0 && i < 0xB6A) continue;      /* the buckets */
        if (i == 0xB76 || i == 0xB77) continue;     /* the LRU head */
        ASSERT_EQ(0, p[i]);
    }
    p = (const uint8_t *)&ACL_$DATA;
    for (i = 0; i < sizeof(ACL_$DATA); i++) {
        ASSERT_EQ(0, p[i]);
    }
}

/* ACL_$UP / ACL_$ENTER_SUPER index with PROC1_$CURRENT, no bias. */
TEST(code_indexes_with_the_pid)
{
    PROC1_$CURRENT = 7;
    ACL_$UP();
    ASSERT_EQ(1, ACL_$DATA.subsys_level[7]);
    ASSERT_EQ(0, ACL_$DATA.subsys_level[6]);
    ACL_$ENTER_SUPER();
    ASSERT_EQ(1, ACL_$UNWIRED_DATA.super_count[7]);
    ASSERT_EQ(0x00E7DACCu + 6 * 2,
              MODULE_DATA_ADDR(ACL_$UNWIRED_DATA) + OFF(ACL_$UNWIRED_DATA, super_count[7]));
    ACL_$DATA.subsys_level[7] = 0;
    ACL_$UNWIRED_DATA.super_count[7] = 0;
}

int main(void)
{
    printf("ACL module data tests\n");
    RUN_TEST(block_addresses_and_sizes);
    RUN_TEST(unwired_offsets);
    RUN_TEST(super_count_pid_n_is_element_n);
    RUN_TEST(data_bias_slots_match_the_displacements);
    RUN_TEST(bias_arms_chain);
    RUN_TEST(pid_n_is_element_n);
    RUN_TEST(initial_contents);
    RUN_TEST(code_indexes_with_the_pid);
    printf("%d tests, %d failed\n", tests_run, tests_failed);
    return tests_failed ? 1 : 0;
}
